#include <stdio.h>

void sort(int *a, int *b, int *c) {
    int temp;
    if (*a > *b) { temp = *a; *a = *b; *b = temp; }
    if (*a > *c) { temp = *a; *a = *c; *c = temp; }
    if (*b > *c) { temp = *b; *b = *c; *c = temp; }
}

int main(void) {
    int v, a, f, p;
    if (scanf("%d %d %d %d", &v, &a, &f, &p) != 4) {
        return 0;
    }

    sort(&a, &f, &p);

    int count = 0;
    if (v >= a) {
        v -= a;
        count++;
        if (v >= f) {
            v -= f;
            count++;
            if (v >= p) {
                v -= p;
                count++;
            }
        }
    }

    printf("%d\n", count);

    return 0;
}
